CREATE OR ALTER PROCEDURE [dbo].[uspCleaningBatch_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ReturnInspectionId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @ResponsibleEmployeeId UNIQUEIDENTIFIER = NULL
	, @CleaningBatchNumber NVARCHAR(MAX) = NULL
	, @StartDate DATETIME2 = NULL
	, @EndDate DATETIME2 = NULL
	, @ContainerQuantity INT = NULL
	, @QualityStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ReturnInspectionId]
			, t.[Quantity]
			, t.[QcResult]
			, t.[Status]
			, t.[CleaningBatchNumber]
			, t.[StartDate]
			, t.[EndDate]
			, t.[ContainerQuantity]
			, t.[ResponsibleEmployeeId]
			, t.[QualityStatus]
			, t.[CreatedDate]
		FROM [dbo].[CleaningBatche] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[CleaningBatchNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ReturnInspectionId IS NULL OR t.[ReturnInspectionId] = @ReturnInspectionId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@ResponsibleEmployeeId IS NULL OR t.[ResponsibleEmployeeId] = @ResponsibleEmployeeId)
			AND (ISNULL(@CleaningBatchNumber, '') = '' OR t.[CleaningBatchNumber] LIKE CONCAT('%', @CleaningBatchNumber, '%'))
			AND (@StartDate IS NULL OR t.[StartDate] = @StartDate)
			AND (@EndDate IS NULL OR t.[EndDate] = @EndDate)
			AND (@ContainerQuantity IS NULL OR t.[ContainerQuantity] = @ContainerQuantity)
			AND (ISNULL(@QualityStatus, '') = '' OR t.[QualityStatus] LIKE CONCAT('%', @QualityStatus, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'returnInspectionId' THEN r.[ReturnInspectionId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'returnInspectionId' THEN r.[ReturnInspectionId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qcResult' THEN r.[QcResult] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qcResult' THEN r.[QcResult] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'cleaningBatchNumber' THEN r.[CleaningBatchNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'cleaningBatchNumber' THEN r.[CleaningBatchNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'startDate' THEN r.[StartDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'startDate' THEN r.[StartDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'endDate' THEN r.[EndDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'endDate' THEN r.[EndDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'containerQuantity' THEN r.[ContainerQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'containerQuantity' THEN r.[ContainerQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'responsibleEmployeeId' THEN r.[ResponsibleEmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'responsibleEmployeeId' THEN r.[ResponsibleEmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
